      }

      // Convertir al formato esperado por apilar (simplificado para la prueba)
      const capasSimples = capasBot1.map(capa => ({ 
        id: capa.id, 
        botId: capa.botId, 
        timestamp: capa.timestamp 
      }));

      // Aplicar apilar sucesivamente
      let resultado: any[] = [];
      capasSimples.forEach(capa => {
        resultado = apilar(resultado, capa);
      });

      // Debe tener exactamente 8 capas
      expect(resultado).toHaveLength(8);

      // Las capas deben ser las 8 más recientes (ids 2-9)
      const idsResultado = resultado.map((c: any) => c.id).sort();
      const idsEsperados = ['capa-2', 'capa-3', 'capa-4', 'capa-5', 'capa-6', 'capa-7', 'capa-8', 'capa-9'].sort();
      expect(idsResultado).toEqual(idsEsperados);

      // La capa más antigua (capa-0 y capa-1) deben haber sido descartadas
      expect(resultado.some((c: any) => c.id === 'capa-0')).toBe(false);
      expect(resultado.some((c: any) => c.id === 'capa-1')).toBe(false);
    });

